; flatworld.s — $E358 dispatch-hook flat plane for the OVERWORLD (mode 1).
; Generated by gen_flatworld.py — do not hand-edit the stubs or the tables.
; Blob base is set by build.py (org $FD0CC, start of the free 0xFF padding).
;
; LAND_K=3 (grass-dominant index), WATER_K=1 (sea-dominant index).
; FLAT_RAM $FF00B0 holds the current flat byte F (set by callsite_stub).

	org $FD0CC

; dispatch_hook: entered via jmp from $E40C (path A) and $E470 (path B).
; On entry: d2 = table index (*4), a6 = $DF58, d6 = dead scratch.
; Stack top = $E358 return address (map_chunk_pos ret for terrain calls).
; Pushes the handler address and rts (computed goto, as the original).
dispatch_hook:
	move.l (a6,d2.w),-(a7)
	btst #2,d2
	beq.s .pathA
	lea.l $434C0,a6
.pathA:
	cmpi.l #$01BC20,32(a7)
	beq.s .terrain
	cmpi.l #$01BC42,32(a7)
	beq.s .terrain
	cmpi.l #$01BC8A,32(a7)
	bne.s .done
.terrain:
	cmpi.w #1,$FF00AE
	bne.s .done
	; grid check: only the overworld grid slot $FFB08C. Room grids are
	; $FFB0AC/$FFB09C/$FFB0BC (world_location_transition $01DC00/$01DC0E/
	; $01DFB2); the overworld branch sets $FFB08C ($01DE08) and boot sets
	; it too ($01B74E). Mode flips to 1 (op-10) BEFORE the grid switches
	; in the room->overworld transition, so mode alone flattens the room
	; floor blue in that window; the grid check closes it.
	move.l $FFA7FC,d6
	cmpi.l #$FFB08C,d6
	bne.s .done
	move.l (flat_table,pc,d2.w),d6
	beq.s .done
	move.l d6,(a7)
	move.b $FF00B0,d5
.done:
	rts

